insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E01","title":"AAD: eczema-friendly products","url":"https://www.aad.org/public/diseases/eczema/childhood/triggers/friendly-products","kind":"학회 안내","publication":"웹 안내","finding":"아토피 아동의 의복으로 헐렁한 면 100%를 안내한다.","limitation":"소재 10종의 비교 순위나 특정 제품의 치료 효과를 증명하지 않는다. 침구 안내를 영아 수면환경 권고로 전용하지 않음.","access":"AAD 공식 본문 직접 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
