insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E03","title":"Functional textiles for atopic dermatitis: systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/23980847/","kind":"체계적 문헌고찰","publication":"2013","finding":"13개 연구를 포함. 기능성 섬유의 치료 권고는 낮은 근거 수준에 기반한 약한 권고였다.","limitation":"오래된 고찰로 이후 대규모 시험과 함께 해석해야 한다.","access":"공개 본문·초록 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E04","title":"CLOTHES: silk garments plus standard care","url":"https://pubmed.ncbi.nlm.nih.gov/28399154/","kind":"무작위 대조시험","publication":"2017","finding":"1~15세 300명, 6개월. 특수 실크 의류 추가군에서 객관적 습진 중증도의 유의한 차이가 없었다.","limitation":"0~3세 전체를 대표하지 않으며 시험 의류와 일반 실크는 다르다. NIHR 지원, 시험 의류 제공 사실 확인.","access":"공개 본문·초록 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E05","title":"DESSINE: superfine wool in infantile eczema","url":"https://onlinelibrary.wiley.com/doi/full/10.1111/bjd.15376","kind":"무작위 교차시험","publication":"2017","finding":"4주~3세 39명, 12주 무작위 교차시험(각6주), 평가자 눈가림. 초극세 메리노울100% 의류를 하루6시간 이상 착용. 6주 SCORAD 차이 −7.6(95% CI −10.4~−4.8) 보고.","limitation":"단일기관·작은 표본. 부모 눈가림 불가, 기존 메리노 반응 병력 및 불안정한 습진 제외. AWI가 자금·의류·세탁제 지원; 저자는 설계·분석·출판 결정에 관여하지 않았다고 명시. 모든 울/중증/개별 판매제품으로 일반화 불가.","access":"2차: 공개 원문 방법·결과·지원기관 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E06","title":"Effects of Merino Wool on Atopic Dermatitis","url":"https://pubmed.ncbi.nlm.nih.gov/30864970/","kind":"교차시험","publication":"2019","finding":"5세 이상 소아·성인을 대상으로 메리노울 의류 사용 시 일부 임상 지표 개선을 보고했다.","limitation":"0~3세 직접 근거가 아니다. 전체 원문과 이해관계 추가 확인.","access":"PubMed 검색 초록 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E07","title":"Fabric preferences of atopic dermatitis patients","url":"https://pubmed.ncbi.nlm.nih.gov/19321117/","kind":"착용 선호도 연구","publication":"2009","finding":"30명 대상 면·리오셀 교차 착용. 리오셀의 촉감 등 선호도는 높았으나 가려움 감소 차이는 유의하지 않았다.","limitation":"성인 관련 연구, 짧은 착용기간. 선호도를 영유아 치료 효과로 해석하지 않는다.","access":"PubMed 공개 초록 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
