insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E09","title":"Real-life evaluation of antibacterial fabrics","url":"https://pubmed.ncbi.nlm.nih.gov/30581460/","kind":"항균 기능 연구","publication":"2018","finding":"건조 착용 조건에서는 실험한 의류가 피부 황색포도상구균 집락을 바꾸지 못했다고 보고한다.","limitation":"시험실 항균성·실제 착용 성능·아토피 개선을 서로 구분해야 한다. 원문 추가 확보.","access":"PubMed 검색 초록 확인","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
insert into public.evidence (id,title,url,kind,publication,finding,limitation,access,checked_at,status) select id,title,url,kind,publication,finding,limitation,access,checked_at,status from json_populate_record(null::public.evidence, '{"id":"E10","title":"ABC trial: antibacterial therapeutic clothing","url":"https://pubmed.ncbi.nlm.nih.gov/37936331/","kind":"무작위 대조시험","publication":"2024","finding":"171명 등록, 159명 분석, 52주. 은·키토산 항균 의류의 추가 이익을 지지하지 않는 결과였다.","limitation":"모든 연령 대상. 0~3세 하위집단 분석 확인 전 직접 적용 보류. 업체의 제한 없는 연구비 지원 등 이해관계가 공개돼 있다. Erasmus MC에 BAP Medical·D&M·DeclaCare의 비제한 지원금 보고. 0~3세 하위집단 효과 별도 미확보.","access":"2차: 저널 공개 페이지 이해관계 원문 확인, 임상 결과는 PubMed 초록","checked_at":"2026-09-30","status":"draft"}'::json) on conflict(id) do nothing;
